<?php

declare(strict_types=1);

use EventMenu\Core\Auth;
use EventMenu\Core\Security;
use EventMenu\Services\MarketplaceDeliveryCouponService;

Auth::requirePermission('coupons.manage');$tenantId=em_require_tenant();$marketCouponService=new MarketplaceDeliveryCouponService();
$moneyToCents=static function(mixed$value):int{$raw=trim((string)$value);if($raw==='')return 0;$raw=str_replace(['R$',' '],'',$raw);if(str_contains($raw,',')&&str_contains($raw,'.'))$raw=str_replace('.','',$raw);$raw=str_replace(',','.',$raw);return max(0,(int)round((float)$raw*100));};
if($_SERVER['REQUEST_METHOD']==='POST'){
    em_post_csrf();$action=(string)($_POST['action']??'');
    if($action==='save'){
        $id=(int)($_POST['id']??0);
        if($id>0&&$marketCouponService->managedCouponId($pdo,$id)!==null){em_flash('error','Este cupom é administrado pelo Super ADM do EventMenu Delivery.');em_go('coupons');}
        $rawCode=mb_strtoupper(trim((string)($_POST['code']??'')));$code=preg_replace('/[^A-Z0-9_-]+/','',$rawCode)??'';if($code===''||mb_strlen($code)>80)exit('Cupom inválido. Use até 80 caracteres: letras, números, _ ou -.');
        $type=(string)($_POST['type']??'percent');$raw=(float)str_replace(',','.',(string)($_POST['value']??'0'));if(!in_array($type,['percent','fixed'],true)||$raw<=0)exit('Cupom inválido.');$value=$type==='percent'?(int)round($raw):(int)round($raw*100);if($type==='percent'&&$value>100)exit('Percentual máximo é 100%.');
        $maxDiscount=$type==='percent'?$moneyToCents($_POST['max_discount']??0):0;$maxDiscount=$maxDiscount>0?$maxDiscount:null;
        $min=$moneyToCents($_POST['min_order']??0);$max=(int)($_POST['max_uses']??0);$start=(string)($_POST['starts_at']??'');$end=(string)($_POST['ends_at']??'');$start=$start?str_replace('T',' ',$start):null;$end=$end?str_replace('T',' ',$end):null;
        if($id){$s=$pdo->prepare('UPDATE coupons SET code=?,type=?,value=?,max_discount_cents=?,min_order_cents=?,max_uses=?,starts_at=?,ends_at=?,active=? WHERE id=? AND tenant_id=?');$s->execute([$code,$type,$value,$maxDiscount,$min,$max?:null,$start,$end,isset($_POST['active'])?1:0,$id,$tenantId]);}
        else{$s=$pdo->prepare('INSERT INTO coupons (tenant_id,code,type,value,max_discount_cents,min_order_cents,max_uses,starts_at,ends_at,active) VALUES (?,?,?,?,?,?,?,?,?,1)');$s->execute([$tenantId,$code,$type,$value,$maxDiscount,$min,$max?:null,$start,$end]);$id=(int)$pdo->lastInsertId();}
        Auth::audit('coupon.saved','coupon',(string)$id,['type'=>$type,'max_discount_cents'=>$maxDiscount]);em_flash('ok','Cupom salvo.');em_go('coupons');
    }
}
$editId=(int)($_GET['edit']??0);$edit=null;if($editId){if($marketCouponService->managedCouponId($pdo,$editId)!==null){em_flash('error','Cupom do EventMenu Delivery é administrado pelo Super ADM.');em_go('coupons');}$s=$pdo->prepare('SELECT * FROM coupons WHERE id=? AND tenant_id=?');$s->execute([$editId,$tenantId]);$edit=$s->fetch()?:null;}
try{$s=$pdo->prepare('SELECT c.*,mt.marketplace_coupon_id FROM coupons c LEFT JOIN marketplace_delivery_coupon_targets mt ON mt.coupon_id=c.id WHERE c.tenant_id=? ORDER BY c.id DESC');$s->execute([$tenantId]);$coupons=$s->fetchAll();}
catch(Throwable){$s=$pdo->prepare('SELECT c.*,NULL marketplace_coupon_id FROM coupons c WHERE c.tenant_id=? ORDER BY c.id DESC');$s->execute([$tenantId]);$coupons=$s->fetchAll();}
em_header('Cupons','coupons');
?><div class="grid" style="grid-template-columns:minmax(280px,1fr) minmax(0,2fr)"><section class="card"><h2><?= $edit?'Editar cupom':'Novo cupom' ?></h2><p class="muted">Cupons criados aqui pertencem somente a esta empresa. Cupons do marketplace são criados pelo Super ADM em <strong>Cupons Delivery</strong>.</p><form method="post" class="form-grid"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="save"><input type="hidden" name="id" value="<?= (int)($edit['id']??0) ?>"><label>Código<input name="code" maxlength="80" required value="<?= Security::e($edit['code']??'') ?>"></label><label>Tipo<select name="type"><option value="percent"<?= em_selected($edit['type']??'percent','percent') ?>>Percentual</option><option value="fixed"<?= em_selected($edit['type']??'','fixed') ?>>Valor fixo</option></select></label><label>Valor<input name="value" inputmode="decimal" required value="<?= $edit?Security::e($edit['type']==='fixed'?number_format(((int)$edit['value'])/100,2,',',''):(string)$edit['value']):'' ?>"></label><label>Desconto máximo (R$)<input name="max_discount" inputmode="decimal" value="<?= $edit&&!empty($edit['max_discount_cents'])?Security::e(number_format(((int)$edit['max_discount_cents'])/100,2,',','')):'' ?>" placeholder="Opcional para percentual"><small>Ex.: 10% com máximo R$ 5,00. Deixe vazio para não limitar.</small></label><label>Pedido mínimo<input name="min_order" inputmode="decimal" value="<?= $edit?Security::e(number_format(((int)$edit['min_order_cents'])/100,2,',','')):'0' ?>"></label><label>Máx. usos<input type="number" name="max_uses" min="0" value="<?= Security::e((string)($edit['max_uses']??'')) ?>"></label><label>Início<input type="datetime-local" name="starts_at" value="<?= $edit&&$edit['starts_at']?Security::e(date('Y-m-d\TH:i',strtotime($edit['starts_at']))):'' ?>"></label><label>Fim<input type="datetime-local" name="ends_at" value="<?= $edit&&$edit['ends_at']?Security::e(date('Y-m-d\TH:i',strtotime($edit['ends_at']))):'' ?>"></label><label class="checkbox"><input type="checkbox" name="active"<?= em_checked($edit?($edit['active']??0):1) ?>> Ativo</label><button class="primary span-2">Salvar cupom</button></form></section><section class="card"><div class="table-wrap"><table class="table"><thead><tr><th>Código</th><th>Origem</th><th>Desconto</th><th>Usos</th><th>Validade</th><th>Status</th><th></th></tr></thead><tbody><?php foreach($coupons as $c):$managed=!empty($c['marketplace_coupon_id']);?><tr><td><strong><?= Security::e($c['code']) ?></strong></td><td><span class="badge status-<?= $managed?'info':'muted' ?>"><?= $managed?'EventMenu Delivery':'Empresa' ?></span></td><td><?= $c['type']==='percent'?(int)$c['value'].'%'.(!empty($c['max_discount_cents'])?' · máx. '.em_money((int)$c['max_discount_cents']):''):em_money($c['value']) ?></td><td><?= (int)$c['uses_count'] ?><?= $c['max_uses']!==null?' / '.(int)$c['max_uses']:'' ?></td><td><?= Security::e($c['ends_at']??'Sem limite') ?></td><td><span class="badge status-<?= $c['active']?'success':'muted' ?>"><?= $c['active']?'Ativo':'Inativo' ?></span></td><td><?php if($managed):?><span class="muted">Gerenciado pelo Super ADM</span><?php else:?><a class="button secondary" href="/?route=coupons&edit=<?= (int)$c['id'] ?>">Editar</a><?php endif;?></td></tr><?php endforeach;?></tbody></table></div></section></div><?php em_footer();
